cheatsheet.code:
{
  "description": "Claim form analyzer",
  "baseAnalyzerId": "prebuilt-document",
  "models": { "completion": "gpt-4.1", "embedding": "text-embedding-3-large" },
  "config": {
    "returnDetails": true,
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "PolicyNumber": { "type": "string", "method": "extract", "description": "Policy ID in the header" },
      "Summary": { "type": "string", "method": "generate", "description": "Two-sentence summary" },
      "Severity": { "type": "string", "method": "classify", "enum": ["Low", "Medium", "High"] }
    }
  }
}

